function hpFilter(data, lambda) {
    const n = data.length;
    // Construct Matrices
    // Minimize (y - t)^T (y - t) + lambda * t^T D^T D t
    // Solution: (I + lambda * D^T D) t = y

    // Matrix A = I + lambda * D^T D
