// --- Update PWT Sheet ---
const pwtSheet = wb.Sheets["PWT"];
const pwtDataOut = [["year", "rnna (Capital Stock)", "rgdpna (Real GDP)"]];
years.filter(y => y <= 2019).forEach(y => {
    pwtDataOut.push([y, rnnaMap.get(y), rgdpnaMap.get(y)]);
});
XLSX.utils.sheet_add_aoa(pwtSheet, pwtDataOut, {origin: "A1"});


// --- Update WEO_Data Sheet ---
const weoSheet = wb.Sheets["WEO_Data"];
// Format: Horizontal Years?
// Existing was: Row 1 headers.
// Let's put a simple table: Year | GDP | Growth
const weoDataOut = [["Year", "Real GDP", "Growth Rate"]];
realGDP.filter(r => r.year >= 2000 && r.year <= 2027).forEach(r => {
    weoDataOut.push([r.year, r.val, r.growth]);
});
XLSX.utils.sheet_add_aoa(weoSheet, weoDataOut, {origin: "A6"}); // Place below existing metadata


// --- Update CFC data Sheet ---
const cfcSheet = wb.Sheets["CFC data"];
const cfcOut = [["Year", "CFC (GEL)", "Capital Stock (PWT)", "Depreciation Rate"]];
// Need linked Capital Stock in Column C?
// Prompt: "Link the capital stock data from 'PWT', and calculate the depreciation rate"
// I will calculate the values and put them, or put formulas.
// Better to put values for CFC, Link formula for K.
cfcData.forEach((d, i) => {
    // Row index start 2
    const row = i + 2;
    // Formula for K: VLOOKUP? Or simple Index?
    // Let's just put the value to ensure it works.
    const depRate = (d.k && d.val) ? (d.val / 2.7) / d.k : ""; // Rough conversion
    cfcOut.push([d.year, d.val, d.k, depRate]);
});
XLSX.utils.sheet_add_aoa(cfcSheet, cfcOut, {origin: "B1"}); // Columns B, C, D, E


// --- Update Production Sheet ---
const prodSheet = wb.Sheets["Production"];
// Setup Years in A6
const startYear = 2002;
const endYear = 2043; // "Assume 2027... until 2043"
const prodYears = [];
for(let y=startYear; y<=endYear; y++) prodYears.push(y);

// Fill A6:A..
const yearCol = prodYears.map(y => [y]);
XLSX.utils.sheet_add_aoa(prodSheet, yearCol, {origin: "A6"});

// Fill Data (K, Y)
// K from PWT (up to 2019). Extended K?
// Step 3: "Extend K by applying a fixed anchor (average K/Y of the most recent 9 yrs)"
// We calculate this in code or formula?
// "You should ONLY use excel... Keep all the formulas".
// Okay, I should setup the formulas.
// But HP filter needs values.
// So I must Populate K and Y Values up to the point needed for HP filter.
// HP Filter usually runs on known history.
// "Link the relevant data... to D6:D27 and E6:E27".
// D6:D27 is 22 years. 2002 to 2023.
// So I fill K and Y for 2002-2023.

const prodData = [];
const lnY_Values = [];
const rows = [];

prodYears.forEach((y, i) => {
    if (y <= 2023) {
        // Known History
        let K = rnnaMap.get(y);
        // If K missing (2020-2023), I need to Extend it NOW for the HP filter input?
        // Wait, HP filter is on LnY (GDP). Not K.
        // Prompt: "Use formula to calculate LnK and LnY. In HP Filter area... smoothed line of LnZ"
        // Usually LnZ is trend of LnY (Total Factor Productivity? No, Z is TFP).
        // Y = K^alpha * (Z * L)^(1-alpha)? Or Y = Z * K^alpha * L^(1-alpha)?
        // Prompt says "Calculate Ystar_base by using lnZ_trend, Y and capital's share".
        // Usually Z is TFP. LnZ = LnY - alpha*LnK - (1-alpha)*LnL.
        // If no L, maybe per worker? Or simple Y = Z * K^alpha?
        // Prompt: "calculate LnK and LnY... smoothed line of LnZ".
        // Implicitly LnZ = LnY - alpha * LnK? (Solow Residual).
        // Yes. I need to calculate Solow Residual first.
        // So I need K and Y for 2002-2023.

        let Y = realGDP.find(r => r.year === y)?.val;

        // Extend K if missing (2020-2023)
        // PWT ends 2019.
        if (!K) {
            // Simple extension: Growth rate of Y? Or Investment?
            // "Extend K by applying a fixed anchor (average K/Y of the most recent 9 yrs)"
            // This instruction is for the PROJECTION part (after 2023).
            // But I need K for 2020-2023 to get Solow Residual (Z).
            // I will extrapolate K using avg growth 2015-2019.
            const k2019 = rnnaMap.get(2019);
            const k2015 = rnnaMap.get(2015);
            const gK = Math.pow(k2019/k2015, 1/4) - 1;
            K = k2019 * Math.pow(1+gK, y - 2019);
        }

        const alpha = 0.35; // Cell B2
        const lnK = Math.log(K);
        const lnY = Math.log(Y);
        const lnZ = lnY - alpha * lnK; // Solow Residual Calculation

        rows.push([K, Y, lnK, lnY, "", "", "", lnZ]); // Cols D, E, F, G, H, I, J, K (LnZ is K?)
        // Wait, looking at Sheet Header:
        // D: K, E: Real GDP, F: LnK, G: LnY.
        // K: LnZ (Label is in K5).
        // L: LnZ_HP.

        lnY_Values.push(lnZ); // We filter Z, not Y? 
        // Prompt: "smoothed line of LnZ". Yes, HP filter on TFP.
    }
});

// Run HP Filter on lnY_Values (which are LnZ)
const lnZ_HP = hpFilter(lnY_Values, 100);

// Fill Production Sheet Data
// D6:G27 (Data), K6:K27 (LnZ), L6:L27 (LnZ_HP)
// Also fill formulas for M (Second-order), N (Check).
// P5 is Objective.

prodData.forEach((row, i) => { // This loop logic is broken, I need to combine data
   // I will construct the full array to write
});

const dataToWrite = [];
for (let i = 0; i < lnY_Values.length; i++) {
    // Cols D, E, F, G.
    // D, E are values. F, G are formulas? "Use formula to calculate LnK and LnY".
    // I will write VALUES for D, E. FORMULAS for F, G.
    // F6 = LN(D6). G6 = LN(E6).
    const r = i + 6;
    const K = rows[i][0];
    const Y = rows[i][1];
    const LnZ = rows[i][7];
    const HP = lnZ_HP[i];

    // We write to columns D, E, (skip F, G formulas), (skip H,I,J), K, L.
    // Actually, I can write the whole block D:L if I manage formulas.
    // I'll write D, E.
    // I'll write K (LnZ Value), L (LnZ_HP Value).
    // I'll write formulas for F, G, M, N.
}

// Write Logic
lnY_Values.forEach((z, i) => {
    const r = i + 6;
    // D, E
    XLSX.utils.sheet_add_aoa(prodSheet, [[rows[i][0], rows[i][1]]], {origin: `D${r}`});
    // F, G Formulas
    XLSX.utils.sheet_add_aoa(prodSheet, [[`=LN(D${r})`, `=LN(E${r})`]], {origin: `F${r}`});
    // K (LnZ calculated manually or formula? "Use formula... to calculate LnZ" - implied.
    // LnZ = LnY - alpha*LnK.
    // Formula for K: =G6 - $B$2*F6
    XLSX.utils.sheet_add_aoa(prodSheet, [[`=G${r}-$B$2*F${r}`]], {origin: `K${r}`});

    // L (HP Filter Result - Hardcoded Value from my solver)
    XLSX.utils.sheet_add_aoa(prodSheet, [[lnZ_HP[i]]], {origin: `L${r}`});

    // M (Second Diff)
    // Formula: = (L6-L5) - (L5-L4)? No.
    // Central difference? or Forward?
    // Usually (L_t - L_t-1) - (L_t-1 - L_t-2) = L_t - 2L_t-1 + L_t-2.
    // For first two rows, it might be 0.
    if (i >= 2) {
        XLSX.utils.sheet_add_aoa(prodSheet, [[`=L${r}-2*L${r-1}+L${r-2}`]], {origin: `M${r}`});
    }

    // N (Check: LnA - Trend). LnA is LnZ? "LnA-Trend(Check)".
    // Formula: = K6 - L6
    XLSX.utils.sheet_add_aoa(prodSheet, [[`=K${r}-L${r}`]], {origin: `N${r}`});
});

// Objective Function in P5
// Sum of Squares of (LnZ - HP) + lambda * Sum of Squares of (2nd Diff).
// Formula: =SUMXMY2(K6:K27, L6:L27) + 100 * SUMSQ(M8:M27)
const objFormula = `=SUMXMY2(K6:K27, L6:L27) + 100*SUMSQ(M8:M27)`;
XLSX.utils.sheet_add_aoa(prodSheet, [[objFormula]], {origin: "P5"});


// 6. Production Function Projection (Step 3)
// "Link the HP filtered LnZ trend to fill G36:G57". Wait, where is G36?
// The sheet has headers. The projection area is likely below.
// "Extend LnZ trend to 2041".
// Use TREND formula.
// "Calculate Ystar_base".
// "Link data from Investment".
// "Calculate deltaK and K_With".

// I need to setup the projection rows (starting 2024? or 2026?)
// The prompt mentions "Investment will last 8 years beginning from 2026".
// So Projection runs 2024-2041?
// "Link the HP filtered LnZ trend to fill G36:G57".
// If Row 36 is where projection starts...
// Let's assume Row 36 corresponds to year 2024?
// (Row 27 was 2023).
// Rows 28-35 might be gap? Or assume continuous.
// If Row 27 is 2023. Row 28 is 2024.
// Row 36 is 2032?
// This requires checking the template. I will check rows 28-40.

XLSX.writeFile(wb, "test-supply.xlsx");

