    XLSX.utils.sheet_add_aoa(prodSheet, [[rows[i][0], rows[i][1]]], {origin: `D${r}`});
    // F, G Formulas
    XLSX.utils.sheet_add_aoa(prodSheet, [[`=LN(D${r})`, `=LN(E${r})`]], {origin: `F${r}`});
    // K (LnZ calculated manually or formula? "Use formula... to calculate LnZ" - implied.
    // LnZ = LnY - alpha*LnK.
    // Formula for K: =G6 - $B$2*F6
    XLSX.utils.sheet_add_aoa(prodSheet, [[`=G${r}-$B$2*F${r}`]], {origin: `K${r}`});

    // L (HP Filter Result - Hardcoded Value from my solver)
    XLSX.utils.sheet_add_aoa(prodSheet, [[lnZ_HP[i]]], {origin: `L${r}`});

    // M (Second Diff)
    // Formula: = (L6-L5) - (L5-L4)? No.
    // Central difference? or Forward?
    // Usually (L_t - L_t-1) - (L_t-1 - L_t-2) = L_t - 2L_t-1 + L_t-2.
    // For first two rows, it might be 0.
    if (i >= 2) {
        XLSX.utils.sheet_add_aoa(prodSheet, [[`=L${r}-2*L${r-1}+L${r-2}`]], {origin: `M${r}`});
    }

    // N (Check: LnA - Trend). LnA is LnZ? "LnA-Trend(Check)".
    // Formula: = K6 - L6
    XLSX.utils.sheet_add_aoa(prodSheet, [[`=K${r}-L${r}`]], {origin: `N${r}`});
});

// Objective Function in P5
// Sum of Squares of (LnZ - HP) + lambda * Sum of Squares of (2nd Diff).
// Formula: =SUMXMY2(K6:K27, L6:L27) + 100 * SUMSQ(M8:M27)
const objFormula = `=SUMXMY2(K6:K27, L6:L27) + 100*SUMSQ(M8:M27)`;
XLSX.utils.sheet_add_aoa(prodSheet, [[objFormula]], {origin: "P5"});


// 6. Production Function Projection (Step 3)
// "Link the HP filtered LnZ trend to fill G36:G57". Wait, where is G36?
// The sheet has headers. The projection area is likely below.
// "Extend LnZ trend to 2041".
// Use TREND formula.
