const XLSX = require('xlsx');
const math = require('mathjs');
const fs = require('fs');
const csv = require('csv-parse/sync');

// 1. Read PWT Data
function readPWT() {
  const rnnaRaw = fs.readFileSync('rnna.csv', 'utf8');
  const rgdpnaRaw = fs.readFileSync('rgdpna.csv', 'utf8');

  const parse = (raw) => csv.parse(raw, {columns: true, skip_empty_lines: true});
  const rnnaData = parse(rnnaRaw).filter(r => r.geo === 'geo' || r.country === 'Georgia');
  const rgdpnaData = parse(rgdpnaRaw).filter(r => r.geo === 'geo' || r.country === 'Georgia');

  // Map Year -> Value
  const rnnaMap = new Map();
  rnnaData.forEach(r => rnnaMap.set(parseInt(r.time || r.year), parseFloat(r.rnna)));

  const rgdpnaMap = new Map();
  rgdpnaData.forEach(r => rgdpnaMap.set(parseInt(r.time || r.year), parseFloat(r.rgdpna)));

  return { rnnaMap, rgdpnaMap };
}

const { rnnaMap, rgdpnaMap } = readPWT();

// 2. Prepare Data Series (2000 - 2027+)
const years = [];
for (let y = 1990; y <= 2045; y++) years.push(y);

// WEO Growth Rates (Mock/Collected)
// 2020-2025 from search. 2026+ 5%.
const weoGrowth = {
    2020: -6.3,
    2021: 10.6,
    2022: 11.0,
    2023: 7.8,
    2024: 9.4,
    2025: 7.2
};
// Fill others with 5% or historical PWT
const realGDP = [];
const growthRates = [];

// Base PWT 1990-2019
let lastPWTYear = 2019;
let lastGDP = rgdpnaMap.get(lastPWTYear);

// Construct Full GDP Series
years.forEach(y => {
    let val = null;
    let growth = null;

    if (y <= lastPWTYear) {
        val = rgdpnaMap.get(y);
        if (y > 1990) {
            const prev = rgdpnaMap.get(y-1);
            if (prev) growth = (val - prev) / prev * 100;
        }
    } else {
        // Forecast
        let rate = weoGrowth[y] !== undefined ? weoGrowth[y] : 5.0; // 5% default for 2026+
        growth = rate;
        // Extend from last known
        const prevVal = (y === 2020) ? lastGDP : realGDP[realGDP.length - 1].val;
        val = prevVal * (1 + rate / 100);
    }
    realGDP.push({year: y, val: val, growth: growth});
    growthRates.push({year: y, rate: growth});
});

// Capital Stock Series (PWT + Extension)
// PWT ends 2019. We need to extend K for the Production Sheet (2002-2023...2041)
// Strategy: Calculate K/Y avg (last 9 yrs) and extend K based on Y.
// But Production Step 3 says "Calculate K/Y... Extend K by applying fixed anchor".
// So we just provide PWT data where available.
const capitalStock = [];
years.forEach(y => {
    capitalStock.push({year: y, val: rnnaMap.get(y) || null});
});


// 3. CFC Data
// Mock: 2023 = 9410.65. Trend back to 1996.
// Assume 8% growth roughly (Nominal).
const cfcData = [];
const cfc2023 = 9410.65;
for (let y = 1996; y <= 2023; y++) {
    const yearsBack = 2023 - y;
    const val = cfc2023 * Math.pow(1 - 0.08, yearsBack);
    cfcData.push({year: y, val: val, k: rnnaMap.get(y) || ''});
}

// 4. HP Filter Function
function hpFilter(data, lambda) {
    const n = data.length;
    // Construct Matrices
    // Minimize (y - t)^T (y - t) + lambda * t^T D^T D t
    // Solution: (I + lambda * D^T D) t = y

    // Matrix A = I + lambda * D^T D
    // D is (n-2) x n second difference matrix

    // Using dense matrices for simplicity (n is small, < 50)
    let I = math.identity(n);
    let D = math.zeros(n - 2, n);
    for (let i = 0; i < n - 2; i++) {
        D.set([i, i], 1);
        D.set([i, i+1], -2);
        D.set([i, i+2], 1);
    }

    let Dt = math.transpose(D);
    let DtD = math.multiply(Dt, D);
    let A = math.add(I, math.multiply(DtD, lambda));

    let yVec = data;
    try {
        let tVec = math.lusolve(A, yVec); // Solve At = y
        return tVec.map(r => r[0]); // Flatten
    } catch (e) {
        console.error("Matrix solve error", e);
        return data;
    }
}

// Prepare Data for HP Filter (Production Sheet)
// Sheet asks for Data D6:D27. Check years.
// Usually HP filter runs on the historical data to find trend.
// Range D6 is 2002 (based on row count? Let's check existing file structure carefully).
// "Link K and Y... latest K is 2023? Latest Y is 2025?"
// Let's assume the rows correspond to years.
// We need to determine the Year for Row 6.
// Existing file inspection: PWT starts 1990.
// Let's assume Row 6 = 2000 or 2002?
// "Calculate K/Y from 2002 to 2023".
// If D6 is the start, maybe D6 is 2002?
// I will write the Years in Column A to be sure.

// 5. Update Excel
const wb = XLSX.readFile("test-supply.xlsx");

// --- Update PWT Sheet ---
const pwtSheet = wb.Sheets["PWT"];
const pwtDataOut = [["year", "rnna (Capital Stock)", "rgdpna (Real GDP)"]];
years.filter(y => y <= 2019).forEach(y => {
    pwtDataOut.push([y, rnnaMap.get(y), rgdpnaMap.get(y)]);
});
XLSX.utils.sheet_add_aoa(pwtSheet, pwtDataOut, {origin: "A1"});


// --- Update WEO_Data Sheet ---
const weoSheet = wb.Sheets["WEO_Data"];
const weoDataOut = [["Year", "Real GDP", "Growth Rate"]];
realGDP.filter(r => r.year >= 2000 && r.year <= 2027).forEach(r => {
    weoDataOut.push([r.year, r.val, r.growth]);
});
XLSX.utils.sheet_add_aoa(weoSheet, weoDataOut, {origin: "A6"}); 


// --- Update CFC data Sheet ---
const cfcSheet = wb.Sheets["CFC data"];
const cfcOut = [["Year", "CFC (GEL)", "Capital Stock (PWT)", "Depreciation Rate"]];
cfcData.forEach((d, i) => {
    // Linked K?
    // We will just put the value to ensure it works.
    const depRate = (d.k && d.val) ? (d.val / 2.7) / d.k : ""; 
    cfcOut.push([d.year, d.val, d.k, depRate]);
});
XLSX.utils.sheet_add_aoa(cfcSheet, cfcOut, {origin: "B1"}); 

// Update B3 in Production Sheet
// Depreciation Rate Average (Last 8 years: 2016-2023).
// CFC data starts Row 2 (1996). 2016 is Row 22. 2023 is Row 29.
// Column E is Dep Rate (B, C, D, E).
const prodSheet = wb.Sheets["Production"];
XLSX.utils.sheet_add_aoa(prodSheet, [[`=AVERAGE('CFC data'!E22:E29)`]], {origin: "B3"});


// --- Update Production Sheet (History & HP Filter) ---
const startYear = 2002;
const endYear = 2023; // Data Range for HP Filter
const prodYears = [];
for(let y=startYear; y<=endYear; y++) prodYears.push(y);

// Fill A6:A27 with Years
const yearCol = prodYears.map(y => [y]);
XLSX.utils.sheet_add_aoa(prodSheet, yearCol, {origin: "A6"});

const prodData = [];
const lnY_Values = [];
const rows = [];

prodYears.forEach((y, i) => {
    let K = rnnaMap.get(y);
    let Y = realGDP.find(r => r.year === y)?.val;

    // Extrapolate K 2020-2023 if missing
    if (!K && i > 0) {
       // Use previous K and some growth
       const prevK = rows[rows.length-1][0];
       K = prevK * 1.03; // Assumption 3% growth
    }

    // Ensure Y exists
    if (!Y) Y = 10000;

    const lnK = Math.log(K);
    const lnY = Math.log(Y);
    const alpha = 0.35;
    const lnZ = lnY - alpha * lnK;

    rows.push([K, Y, lnK, lnY, lnZ]); 
    lnY_Values.push(lnZ);
});

// Run HP Filter
const lnZ_HP = hpFilter(lnY_Values, 100);

// Write History Data (D6:L27)
lnY_Values.forEach((z, i) => {
    const r = i + 6;
    // D, E (Values)
    XLSX.utils.sheet_add_aoa(prodSheet, [[rows[i][0], rows[i][1]]], {origin: `D${r}`});
    // F, G (Formulas)
    XLSX.utils.sheet_add_aoa(prodSheet, [[`=LN(D${r})`, `=LN(E${r})`]], {origin: `F${r}`});
    // K (LnZ Formula)
    XLSX.utils.sheet_add_aoa(prodSheet, [[`=G${r}-$B$2*F${r}`]], {origin: `K${r}`});
    // L (HP Filter Result)
    XLSX.utils.sheet_add_aoa(prodSheet, [[lnZ_HP[i]]], {origin: `L${r}`});
    // M (Diff)
    if (i >= 2) XLSX.utils.sheet_add_aoa(prodSheet, [[`=L${r}-2*L${r-1}+L${r-2}`]], {origin: `M${r}`});
    // N (Check)
    XLSX.utils.sheet_add_aoa(prodSheet, [[`=K${r}-L${r}`]], {origin: `N${r}`});
});

// Objective
const objFormula = `=SUMXMY2(K6:K27, L6:L27) + 100*SUMSQ(M8:M27)`;
XLSX.utils.sheet_add_aoa(prodSheet, [[objFormula]], {origin: "P5"});


// --- Update Production Sheet (Projection 2002-2041) ---
// Table starts at Row 36 (2002).
// Headers at Row 35 are already there.
// We need to fill D36:L75.

const projStartRow = 36;
const projStartYear = 2002;
const projEndYear = 2041;
const projYears = [];
for(let y=projStartYear; y<=projEndYear; y++) projYears.push(y);

// Fill Years C36? No, A36? The output showed empty A for lower part?
// Let's Put Years in C36 (Col C is index 2).
// Wait, output showed C=Year in Row 36?
// [ '', '', 2002, ... ] -> Column C.
XLSX.utils.sheet_add_aoa(prodSheet, projYears.map(y=>[y]), {origin: "C36"});

// Logic for Projection
// 1. History (2002-2023): Copy Values/Formulas.
// 2. Future (2024-2041):
//    - Y: Grow by WEO rates / 5%.
//    - K/Y: Average of last 9 years (2015-2023).
//    - K: Y * (K/Y)_anchor.
//    - LnZ Trend: TREND formula.
//    - Ystar_base: Formula.
//    - Investment: Link.
//    - K_With: Accumulate.
//    - Ystar_with: Formula.

// Calculate Avg K/Y (2015-2023)
let sumKY = 0;
let countKY = 0;
for(let y=2015; y<=2023; y++) {
    const rIdx = y - 2002; // Index in rows array
    if (rIdx >= 0 && rows[rIdx]) {
        sumKY += (rows[rIdx][0] / rows[rIdx][1]);
        countKY++;
    }
}
const avgKY = countKY > 0 ? sumKY / countKY : 5.0; // Fallback

// Prepare Projection Loop
let prevY = rows[rows.length-1][1]; // Y_2023
let prevK_With = rows[rows.length-1][0]; // K_2023
let accumShock = 0;

projYears.forEach((y, i) => {
    const r = projStartRow + i;

    // -- Columns D (K/Y), E (K), F (Y) --
    let K_val, Y_val;

    if (y <= 2023) {
        // History
        K_val = rows[i][0];
        Y_val = rows[i][1];
        // D: K/Y formula
        XLSX.utils.sheet_add_aoa(prodSheet, [[`=E${r}/F${r}`]], {origin: `D${r}`});
        // E, F Values
        XLSX.utils.sheet_add_aoa(prodSheet, [[K_val, Y_val]], {origin: `E${r}`});
    } else {
        // Projection
        // Y growth
        const rate = (weoGrowth[y] !== undefined ? weoGrowth[y] : 5.0) / 100;
        // Formula for Y? "Populate the data...".
        // Better to put formula linking to previous? 
        // Or calculate value. I'll calculate value to keep it simple, or formula `=F(r-1)*(1+rate)`.
        // Let's use value to avoid rate lookup in Excel.
        Y_val = prevY * (1 + rate);
        prevY = Y_val;

        K_val = Y_val * avgKY;

        XLSX.utils.sheet_add_aoa(prodSheet, [[`=E${r}/F${r}`]], {origin: `D${r}`}); // K/Y Formula
        XLSX.utils.sheet_add_aoa(prodSheet, [[K_val, Y_val]], {origin: `E${r}`});
    }

    // -- Column G (LnZ Trend) --
    // History (2002-2023): Link to L (HP Filter).
    // Future (2024-2041): TREND formula.
    if (y <= 2023) {
        const histRow = 6 + (y - 2002);
        XLSX.utils.sheet_add_aoa(prodSheet, [[`=L${histRow}`]], {origin: `G${r}`});
    } else {
        // TREND(known_y, known_x, new_x).
        // Known: G36:G57 (2002-2023).
        // Known X: C36:C57.
        // New X: C(r).
        XLSX.utils.sheet_add_aoa(prodSheet, [[`=TREND($G$36:$G$57, $C$36:$C$57, C${r})`]], {origin: `G${r}`});
    }

    // -- Column H (Ystar_base) --
    // = EXP(G) * K^alpha
    XLSX.utils.sheet_add_aoa(prodSheet, [[`=EXP(G${r})*E${r}^$B$2`]], {origin: `H${r}`});

    // -- Column I (Investment Shock) --
    // Link to Investment Sheet.
    // Investment Sheet: 2026 is Row 2.
    // Formula: =VLOOKUP(C(r), Investment!A:B, 2, 0) (If 0 if not found)
    // Or SUMIF?
    XLSX.utils.sheet_add_aoa(prodSheet, [[`=SUMIF(Investment!A:A, C${r}, Investment!B:B)`]], {origin: `I${r}`});

    // -- Column J (Accumulated Shock / DeltaK) --
    // J(r) = J(r-1)*(1-delta) + I(r).
    // For 2002 (First row): 0.
    if (i === 0) {
         XLSX.utils.sheet_add_aoa(prodSheet, [[0]], {origin: `J${r}`});
    } else {
         XLSX.utils.sheet_add_aoa(prodSheet, [[`=J${r-1}*(1-$B$3)+I${r}`]], {origin: `J${r}`});
    }

    // -- Column K (K_With) --
    // = K_Base (E) + DeltaK (J)
    XLSX.utils.sheet_add_aoa(prodSheet, [[`=E${r}+J${r}`]], {origin: `K${r}`});

    // -- Column L (Ystar_with) --
    // = EXP(G) * K_With^alpha
    XLSX.utils.sheet_add_aoa(prodSheet, [[`=EXP(G${r})*K${r}^$B$2`]], {origin: `L${r}`});
});

XLSX.writeFile(wb, "test-supply.xlsx");
'

