// Calculate Avg K/Y (2015-2023)
let sumKY = 0;
let countKY = 0;
for(let y=2015; y<=2023; y++) {
    const rIdx = y - 2002; // Index in rows array
    if (rIdx >= 0 && rows[rIdx]) {
        sumKY += (rows[rIdx][0] / rows[rIdx][1]);
        countKY++;
    }
}
const avgKY = countKY > 0 ? sumKY / countKY : 5.0; // Fallback

// Prepare Projection Loop
let prevY = rows[rows.length-1][1]; // Y_2023
let prevK_With = rows[rows.length-1][0]; // K_2023
let accumShock = 0;

projYears.forEach((y, i) => {
    const r = projStartRow + i;

    // -- Columns D (K/Y), E (K), F (Y) --
    let K_val, Y_val;

    if (y <= 2023) {
        // History
        K_val = rows[i][0];
        Y_val = rows[i][1];
        // D: K/Y formula
        XLSX.utils.sheet_add_aoa(prodSheet, [[`=E${r}/F${r}`]], {origin: `D${r}`});
        // E, F Values
        XLSX.utils.sheet_add_aoa(prodSheet, [[K_val, Y_val]], {origin: `E${r}`});
    } else {
        // Projection
        // Y growth
        const rate = (weoGrowth[y] !== undefined ? weoGrowth[y] : 5.0) / 100;
        // Formula for Y? "Populate the data...".
        // Better to put formula linking to previous? 
        // Or calculate value. I'll calculate value to keep it simple, or formula `=F(r-1)*(1+rate)`.
        // Let's use value to avoid rate lookup in Excel.
        Y_val = prevY * (1 + rate);
        prevY = Y_val;

        K_val = Y_val * avgKY;

        XLSX.utils.sheet_add_aoa(prodSheet, [[`=E${r}/F${r}`]], {origin: `D${r}`}); // K/Y Formula
        XLSX.utils.sheet_add_aoa(prodSheet, [[K_val, Y_val]], {origin: `E${r}`});
    }

    // -- Column G (LnZ Trend) --
    // History (2002-2023): Link to L (HP Filter).
    // Future (2024-2041): TREND formula.
    if (y <= 2023) {
        const histRow = 6 + (y - 2002);
        XLSX.utils.sheet_add_aoa(prodSheet, [[`=L${histRow}`]], {origin: `G${r}`});
    } else {
        // TREND(known_y, known_x, new_x).
        // Known: G36:G57 (2002-2023).
        // Known X: C36:C57.
        // New X: C(r).
        XLSX.utils.sheet_add_aoa(prodSheet, [[`=TREND($G$36:$G$57, $C$36:$C$57, C${r})`]], {origin: `G${r}`});
    }

    // -- Column H (Ystar_base) --
    // = EXP(G) * K^alpha
    XLSX.utils.sheet_add_aoa(prodSheet, [[`=EXP(G${r})*E${r}^$B$2`]], {origin: `H${r}`});

    // -- Column I (Investment Shock) --
    // Link to Investment Sheet.
    // Investment Sheet: 2026 is Row 2.
    // Formula: =VLOOKUP(C(r), Investment!A:B, 2, 0) (If 0 if not found)
    // Or SUMIF?
    XLSX.utils.sheet_add_aoa(prodSheet, [[`=SUMIF(Investment!A:A, C${r}, Investment!B:B)`]], {origin: `I${r}`});

    // -- Column J (Accumulated Shock / DeltaK) --
    // J(r) = J(r-1)*(1-delta) + I(r).
    // For 2002 (First row): 0.
    if (i === 0) {
         XLSX.utils.sheet_add_aoa(prodSheet, [[0]], {origin: `J${r}`});
    } else {
         XLSX.utils.sheet_add_aoa(prodSheet, [[`=J${r-1}*(1-$B$3)+I${r}`]], {origin: `J${r}`});
    }

    // -- Column K (K_With) --
    // = K_Base (E) + DeltaK (J)
    XLSX.utils.sheet_add_aoa(prodSheet, [[`=E${r}+J${r}`]], {origin: `K${r}`});

    // -- Column L (Ystar_with) --
    // = EXP(G) * K_With^alpha
    XLSX.utils.sheet_add_aoa(prodSheet, [[`=EXP(G${r})*K${r}^$B$2`]], {origin: `L${r}`});
});

// FIX: Convert strings starting with "=" to Formulas
function fixFormulas(sheet) {
    for (const key in sheet) {
        if (key.startsWith('!')) continue;
        const cell = sheet[key];
        if (cell.t === 's' && cell.v && typeof cell.v === 'string' && cell.v.startsWith('=')) {
            cell.f = cell.v.substring(1);
            cell.v = 0; // Dummy value
            cell.t = 'n'; // Set type to number
        }
    }
}
fixFormulas(prodSheet);
fixFormulas(cfcSheet); // Fix CFC sheet too if any

XLSX.writeFile(wb, "test-supply.xlsx");

